create index if not exists goals_owner_user_id_idx on public.goals(owner_user_id) where owner_user_id is not null; drop policy if exists agent_registry_self_read on public.agent_registry; create policy agent_registry_self_read on public.agent_registry for select to authenticated using (user_id=(select auth.uid())); drop policy if exists goals_owner_access on public.goals; create policy goals_owner_access on public.goals for all to authenticated using (owner_user_id=(select auth.uid())) with check (owner_user_id=(select auth.uid()));